$content = Get-Content "backend\controllers\ticketController.js" -Raw
$content = $content -replace "        if \(ticket.status === 'cancelled'\) \{\n            return res.json\(\{ success: true, status: `"DENIED`", message: `"Ticket Cancelled`", ticket: \{ _id: ticket._id, name: ticket.name \}, data: \{ _id: ticket._id, name: ticket.name \} \}\);\n        \}\n            return res.json\(\{ success: true, status: `"DENIED`", message: currentAmountPaid > 0 \? ``?\$\{currentRemaining\} payment remaining`` : ``Payment Pending``, ticket: \{ _id: ticket._id, name: ticket.name \}, data: \{ _id: ticket._id, name: ticket.name \} \}\);\n        \}", "        if (ticket.status === 'cancelled') {`n            return res.json({ success: true, status: `"DENIED`", message: `"Ticket Cancelled`", ticket: { _id: ticket._id, name: ticket.name }, data: { _id: ticket._id, name: ticket.name } });`n        }`n`n        if (!isPaid) {`n            return res.json({ success: true, status: `"DENIED`", message: currentAmountPaid > 0 ? ``?${currentRemaining} payment remaining`` : ``Payment Pending``, ticket: { _id: ticket._id, name: ticket.name }, data: { _id: ticket._id, name: ticket.name } });`n        }"
Set-Content "backend\controllers\ticketController.js" $content
